1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSlideIndicator } from '../zimmSlideIndicator';
5	import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
6	
7	/**
8	 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
9	 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
10	 * these descendants for hover-reveal styling without reaching into implementation details.
11	 * Do not rename these values without updating that recipe too:
12	 *   - "media"     — the outermost element (this component's root)
13	 *   - "tag"       — the badge overlay wrapper (present only when `badge` is supplied)
14	 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
15	 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
16	 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
17	 */
18	
19	const messages = defineMessages({
20	  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
21	  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
22	  /**
23	   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
24	   * distinct from the hover-capable-only `carousel` arrows and the touch-only
25	   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
26	   * pointer capability. See `canNavigateByKeyboard` below.
27	   */
28	  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
29	});
30	
31	const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';
32	
33	/** One image the card can show — always a real, non-empty product-photo description. */
34	export type ZimmProductCardMediaImage = {
35	  src: string;
36	  alt: string;
37	};
38	
39	export type ZimmProductCardMediaProps = {
40	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
41	  primaryImage: ZimmProductCardMediaImage;
42	  /**
43	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
44	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
45	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
46	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
47	   * content. Has no effect unless `swapOnHover` is also true.
48	   */
49	  hoverImage?: ZimmProductCardMediaImage;
50	  /**
51	   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
52	   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
53	   * `hoverImage`'s note above for why the two features don't combine).
54	   */
55	  images?: ZimmProductCardMediaImage[];
56	  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
57	  swapOnHover: boolean;
58	  /**
59	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
60	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
61	   * — it renders whenever there is more than one image to page through, regardless of this prop.
62	   */
63	  showControls: boolean;
64	  /**
65	   * Renders inside a positioned, non-interactive top-left slot. This component does not style
66	   * the content itself — SPR-16 / .docs/prd/plp.md §2.6: PLP badges are display-only.
67	   */
68	  badge?: React.ReactNode;
69	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
70	  onRemove?: () => void;
71	  /**
72	   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
73	   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
74	   * independent optional props rather than a discriminated union because this is a simple
75	   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
76	   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
77	   * all rather than shipping an unlabelled, inaccessible button — see the component body.
78	   */
79	  removeLabel?: string;
80	  /**
81	   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
82	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
83	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
84	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
85	   */
86	  priority?: boolean;
87	};
88	
89	/**
90	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
91	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the badge and
92	 * wishlist-remove overlay slots. Figma "Image Group" component set, node 40002742:46323.
93	 *
94	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
95	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
96	 * the slide indicator are mutually exclusive by pointer capability
97	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
98	 * exist in the DOM at all times and are gated by the recipe's own CSS media query rather than a
99	 * JS `window.matchMedia` check — matching the "keep in DOM, hide via CSS" precedent
100	 * `ZimmColourSwatchGroup` already uses for its off-page swatches — so server and client render
101	 * identically (no hydration mismatch) and neither affordance depends on `matchMedia`, which
102	 * jsdom (this component's own Vitest environment) does not implement.
103	 *
104	 * A third, always-available operability layer sits underneath both visual affordances: the
105	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
106	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
107	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
108	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
109	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
110	 */
111	export const ZimmProductCardMedia = ({
112	  primaryImage,
113	  hoverImage,
114	  images,
115	  swapOnHover,
116	  showControls,
117	  badge,
118	  onRemove,
119	  removeLabel,
120	  priority,
121	}: ZimmProductCardMediaProps) => {
122	  const intl = useIntl();
123	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
124	
125	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
126	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
127	  const gallery = images && images.length > 1 ? images : undefined;
128	  const slideImages = gallery ?? [primaryImage];
129	  const totalSlides = slideImages.length;
130	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
131	  const canPage = totalSlides > 1 && showControls;
132	  // Keyboard operability is independent of `showControls` — deliberately not folded into
133	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
134	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
135	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
136	  // so this is the only paging affordance such a user has, regardless of `showControls`.
137	  const canNavigateByKeyboard = totalSlides > 1;
138	
139	  // Single piece of state, per this codebase's extract-to-hook threshold
140	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
141	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
142	  // because this build step's file manifest is limited to this component's own 4 files; a hook
143	  // would be a 5th file outside that scope.
144	  const [currentIndex, setCurrentIndex] = useState(0);
145	  const scrollContainerRef = useRef<HTMLDivElement>(null);
146	
147	  const scrollToIndex = (index: number) => {
148	    const container = scrollContainerRef.current;
149	    if (!container || typeof container.scrollTo !== 'function') return;
150	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
151	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
152	    // browser reports a real width so the requested slide scrolls fully into view.
153	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
154	  };
155	
156	  const goToRelativeSlide = (delta: 1 | -1) => {
157	    if (totalSlides <= 1) return;
158	    const next = (currentIndex + delta + totalSlides) % totalSlides;
159	    setCurrentIndex(next);
160	    scrollToIndex(next);
161	  };
162	
163	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
164	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
165	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
166	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
167	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
168	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
169	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
170	  useEffect(() => {
171	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
172	  }, [totalSlides]);
173	
174	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
175	  // capability — additive to, and independent of, the hover-capable-only arrows and the
176	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
177	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
178	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
179	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
180	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
181	    event.preventDefault();
182	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
183	  };
184	
185	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
186	  // calls goToRelativeSlide at all. `scrollend` (Baseline 2024 — Chrome 114+, Firefox 109+,
187	  // Safari 18+) fires once the snap gesture settles. No `scroll`-event fallback for older
188	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
189	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
190	  // interaction.
191	  useEffect(() => {
192	    const container = scrollContainerRef.current;
193	    if (!container || totalSlides <= 1) return undefined;
194	
195	    const handleScrollEnd = () => {
196	      const slideWidth = container.clientWidth || 1;
197	      const nearest = Math.round(container.scrollLeft / slideWidth);
198	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
199	    };
200	
201	    container.addEventListener('scrollend', handleScrollEnd);
202	    return () => container.removeEventListener('scrollend', handleScrollEnd);
203	  }, [totalSlides]);
204	
205	  // Non-primary images are always lazy; only the first slide's own base image can opt into
206	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
207	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
208	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
209	
210	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
211	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
212	
213	  return (
214	    <chakra.div __css={styles.root} data-card-slot="media">
215	      <chakra.div
216	        ref={scrollContainerRef}
217	        __css={styles.scrollContainer}
218	        data-testid="card-media-scroll"
219	        role={canNavigateByKeyboard ? 'group' : undefined}
220	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
221	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
222	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
223	      >
224	        {slideImages.map((image, index) => {
225	          const isPrimaryPosition = index === 0;
226	
227	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
228	            return (
229	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
230	                <chakra.img
231	                  src={image.src}
232	                  alt={image.alt}
233	                  data-role="hover-base"
234	                  __css={styles.hoverSwapBase}
235	                  {...imageLoadingProps(true)}
236	                />
237	                <chakra.img
238	                  src={hoverImage.src}
239	                  alt={hoverImage.alt}
240	                  data-role="hover-overlay"
241	                  __css={styles.hoverSwapOverlay}
242	                  {...imageLoadingProps(false)}
243	                />
244	              </chakra.div>
245	            );
246	          }
247	
248	          return (
249	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
250	              <chakra.img
251	                src={image.src}
252	                alt={image.alt}
253	                __css={styles.image}
254	                {...imageLoadingProps(isPrimaryPosition)}
255	              />
256	            </chakra.div>
257	          );
258	        })}
259	      </chakra.div>
260	
261	      {badge != null && (
262	        // Non-interactive by design — SPR-16 / .docs/prd/plp.md §2.6: PLP badges are
263	        // display-only. Figma's Tag/Badge component set technically ships a touchContainer +
264	        // State=Hover variant, but that clickable-badge request is a NEW, unsigned request —
265	        // do not wire up any hover/click behaviour here.
266	        <chakra.div __css={styles.tag} data-card-slot="tag">
267	          {badge}
268	        </chakra.div>
269	      )}
270	
271	      {showRemove && (
272	        <chakra.button
273	          type="button"
274	          __css={styles.close}
275	          data-card-slot="close"
276	          aria-label={removeLabel}
277	          onClick={onRemove}
278	        >
279	          <CloseIcon aria-hidden />
280	        </chakra.button>
281	      )}
282	
283	      {canPage && (
284	        <chakra.div __css={styles.carousel} data-card-slot="carousel">
285	          <chakra.button
286	            type="button"
287	            __css={styles.arrowButton}
288	            aria-label={intl.formatMessage(messages.previousImage)}
289	            onClick={() => goToRelativeSlide(-1)}
290	          >
291	            <ChevronLeftIcon aria-hidden />
292	          </chakra.button>
293	          <chakra.button
294	            type="button"
295	            __css={styles.arrowButton}
296	            aria-label={intl.formatMessage(messages.nextImage)}
297	            onClick={() => goToRelativeSlide(1)}
298	          >
299	            <ChevronRightIcon aria-hidden />
300	          </chakra.button>
301	        </chakra.div>
302	      )}
303	
304	      {totalSlides > 1 && (
305	        <chakra.div __css={styles.indicatorWrapper} data-card-slot="indicator">
306	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
307	        </chakra.div>
308	      )}
309	    </chakra.div>
310	  );
311	};
312	
313	export default ZimmProductCardMedia;
314

1	/**
2	 * Scoped per testing.md: this component's own contract (given props, does it render the right
3	 * branch and wire the right handler) — not ZimmSlideIndicator's own segment/clamp logic, which
4	 * is proven in its own index.test.tsx and rendered here for real (it is a lightweight,
5	 * side-effect-free presentational atom, so composing it directly costs nothing and gives real
6	 * integration confidence that this component passes it the right `count`/`activeIndex`).
7	 */
8	import React from 'react';
9	import { describe, test, expect, vi } from 'vitest';
10	import { render, screen, fireEvent } from '@testing-library/react';
11	import userEvent from '@testing-library/user-event';
12	import { IntlProvider } from 'react-intl';
13	import { ZimmProductCardMedia } from './index';
14	import type { ZimmProductCardMediaImage } from './index';
15	import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from './zimmProductCardMedia.css';
16	
17	// Flat parts object covering both this component's own recipe AND ZimmSlideIndicator's
18	// (root/dot) — the same mocked useMultiStyleConfig is shared by both since neither test setup
19	// nor Chakra itself cares which recipe name asked for it. Same precedent as
20	// zimmSizeChipGroup/index.test.tsx's comment on its composed atom's unresolved styles.chip.
21	vi.mock('@chakra-ui/react', async (importOriginal) => {
22	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
23	  return {
24	    ...actual,
25	    useMultiStyleConfig: () => ({
26	      root: {},
27	      scrollContainer: {},
28	      slide: {},
29	      image: {},
30	      hoverSwapBase: {},
31	      hoverSwapOverlay: {},
32	      tag: {},
33	      close: {},
34	      carousel: {},
35	      arrowButton: {},
36	      indicatorWrapper: {},
37	      dot: {},
38	    }),
39	  };
40	});
41	
42	// ChevronLeftIcon / ChevronRightIcon / CloseIcon: the icons barrel has the Vitest SVG
43	// side-effect issue documented in .claude/rules/testing.md's "Known gap: ZimmIcon throws under
44	// Vitest" section. Mocked at the same relative specifier this component imports them from.
45	vi.mock('../../../icons', () => ({
46	  ChevronLeftIcon: () => null,
47	  ChevronRightIcon: () => null,
48	  CloseIcon: () => null,
49	}));
50	
51	const wrap = (ui: React.ReactElement) =>
52	  render(
53	    <IntlProvider locale="en" defaultLocale="en">
54	      {ui}
55	    </IntlProvider>,
56	  );
57	
58	const PRIMARY: ZimmProductCardMediaImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
59	const HOVER: ZimmProductCardMediaImage = { src: 'hover.jpg', alt: 'Zimmermann dress, on model' };
60	const GALLERY: ZimmProductCardMediaImage[] = [
61	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
62	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
63	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
64	];
65	
66	/** Mocks the scroll container's native `scrollTo` (absent under jsdom — see index.tsx's own
67	 *  comment) so an arrow click can be asserted against a spy instead of throwing. */
68	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
69	  // HTMLElement already types `scrollTo` (lib.dom.d.ts) — jsdom just doesn't implement it at
70	  // runtime, so a plain mock-function assignment is enough; no cast needed.
71	  const scrollContainer = screen.getByTestId('card-media-scroll');
72	  const scrollTo = vi.fn();
73	  scrollContainer.scrollTo = scrollTo;
74	  return scrollTo;
75	};
76	
77	describe('ZimmProductCardMedia — AC1: primary image renders with minimal props', () => {
78	  test('renders the primary image when hoverImage, images and showControls are all absent/false', () => {
79	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
80	    const img = screen.getByRole('img', { name: PRIMARY.alt });
81	    expect(img).toHaveAttribute('src', PRIMARY.src);
82	  });
83	});
84	
85	describe('ZimmProductCardMedia — alt text', () => {
86	  test('every rendered gallery image carries its own meaningful alt text', () => {
87	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
88	    GALLERY.forEach((image) => {
89	      expect(screen.getByRole('img', { name: image.alt })).toBeInTheDocument();
90	    });
91	  });
92	
93	  test('a hover-swap pair keeps both images accessible by their own alt text', () => {
94	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} />);
95	    expect(screen.getByRole('img', { name: PRIMARY.alt })).toBeInTheDocument();
96	    expect(screen.getByRole('img', { name: HOVER.alt })).toBeInTheDocument();
97	  });
98	});
99	
100	describe('ZimmProductCardMedia — lazy/eager loading', () => {
101	  test('the primary image lazy-loads by default (priority absent)', () => {
102	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
103	    const img = screen.getByRole('img', { name: PRIMARY.alt });
104	    expect(img).toHaveAttribute('loading', 'lazy');
105	    expect(img).toHaveAttribute('decoding', 'async');
106	  });
107	
108	  test('the primary image loads eagerly when priority is true', () => {
109	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} priority />);
110	    const img = screen.getByRole('img', { name: PRIMARY.alt });
111	    expect(img).not.toHaveAttribute('loading');
112	    expect(img).toHaveAttribute('decoding', 'async');
113	  });
114	
115	  test('non-primary gallery images are always lazy, even when priority is true', () => {
116	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls priority />);
117	    expect(screen.getByRole('img', { name: GALLERY[0].alt })).not.toHaveAttribute('loading');
118	    expect(screen.getByRole('img', { name: GALLERY[1].alt })).toHaveAttribute('loading', 'lazy');
119	    expect(screen.getByRole('img', { name: GALLERY[2].alt })).toHaveAttribute('loading', 'lazy');
120	  });
121	
122	  test('the hover-swap overlay image is always lazy, even when priority is true', () => {
123	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} swapOnHover showControls={false} priority />);
124	    expect(screen.getByRole('img', { name: PRIMARY.alt })).not.toHaveAttribute('loading');
125	    expect(screen.getByRole('img', { name: HOVER.alt })).toHaveAttribute('loading', 'lazy');
126	  });
127	});
128	
129	describe('ZimmProductCardMedia — single image renders no paging affordance', () => {
130	  test('renders no arrow buttons and no slide indicator, even when showControls is true', () => {
131	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls />);
132	    expect(screen.queryAllByRole('button')).toHaveLength(0);
133	    expect(screen.queryByRole('group')).not.toBeInTheDocument(); // ZimmSlideIndicator's role=group
134	  });
135	
136	  test('a 1-entry images array behaves identically to an absent images array', () => {
137	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={[GALLERY[0]]} swapOnHover={false} showControls />);
138	    expect(screen.queryAllByRole('button')).toHaveLength(0);
139	    expect(screen.queryByRole('group')).not.toBeInTheDocument();
140	  });
141	});
142	
143	describe('ZimmProductCardMedia — arrows wrap at both ends', () => {
144	  test('Next from the last image wraps to the first, updates the indicator, and calls scrollTo with a plausible shape', async () => {
145	    const user = userEvent.setup();
146	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
147	    const scrollTo = mockScrollTo();
148	
149	    const next = screen.getByRole('button', { name: 'Next image' });
150	    await user.click(next); // 0 -> 1
151	    await user.click(next); // 1 -> 2 (last)
152	    scrollTo.mockClear();
153	    await user.click(next); // wraps 2 -> 0
154	
155	    expect(scrollTo).toHaveBeenCalledTimes(1);
156	    // jsdom reports clientWidth as 0 regardless of index, so the numeric offset itself cannot
157	    // prove which slide was requested — only that a plausible {left, behavior} shape was sent.
158	    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
159	    // The logical wrap is proven via the composed (real, unmocked) slide indicator's accessible
160	    // name, which reflects `activeIndex` from pure component state regardless of jsdom layout.
161	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
162	  });
163	
164	  test('Previous from the first image wraps to the last, updates the indicator, and calls scrollTo with a plausible shape', async () => {
165	    const user = userEvent.setup();
166	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
167	    const scrollTo = mockScrollTo();
168	
169	    const previous = screen.getByRole('button', { name: 'Previous image' });
170	    await user.click(previous); // wraps 0 -> 2 (last)
171	
172	    expect(scrollTo).toHaveBeenCalledTimes(1);
