353	describe('ZimmProductCardMedia — scrollend listener drives the touch indicator (Fix 4 regression)', () => {
354	  test('a real scrollend event with a simulated scroll position updates the indicator', () => {
355	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
356	    const container = screen.getByTestId('card-media-scroll');
357	
358	    // jsdom performs no real layout, so clientWidth/scrollWidth/scrollLeft all default to 0 —
359	    // but they ARE plain definable properties, so a real geometry can be simulated directly.
360	    // Slide width 300 x 3 slides, scrolled to slide index 1 (the 2nd of 3) => scrollLeft 300.
361	    const SIMULATED_SLIDE_WIDTH = 300;
362	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
363	    Object.defineProperty(container, 'scrollWidth', {
364	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
365	      configurable: true,
366	    });
367	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * 1, configurable: true });
368	
369	    // A raw `container.dispatchEvent(...)` bypasses @testing-library/react's configured
370	    // `eventWrapper`, so the resulting setCurrentIndex call is never flushed before the
371	    // assertion below runs. Routing the same native Event through RTL's generic `fireEvent`
372	    // call form (not one of its `fireEvent.<type>` convenience methods — `scrollend` isn't one
373	    // of those) dispatches the identical event while going through that act()-wrapping config.
374	    fireEvent(container, new Event('scrollend'));
375	
376	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
377	  });
378	});
